// Une seule entrée pour le LLM : la liste compacte des candidats (id | sujet | source | titre)
const user = $('Utilisateur').first().json;
const news = $input.all().map(i => i.json).filter(n => n.id);
if (news.length === 0) return [];   // rien de neuf pour cet utilisateur
const list = news.map(n => `${n.id} | ${n.topic_slug} | ${n.source} | ${n.title}`).join('\n');
return [{ json: { user_id: user.id, keywords: user.keywords || [], count: news.length, list } }];

// Garde-fous après le classement du LLM :
// 1. on ne garde que des id présents dans les candidats (le LLM ne peut rien inventer)
// 2. on écarte les doublons de sujet : titres qui partagent un nom propre (Nvidia, COP31…) ou 2 mots significatifs
// 3. on écarte les promos ; si la liste est trop courte, on complète avec les news les plus récentes
const MAX = 6;
const cands = $('Candidats').all().map(i => i.json).filter(n => n.id);
const byId = new Map(cands.map(n => [String(n.id), n]));
let ids = [];
try {
  // Avec le format JSON d'Ollama, la chaîne renvoie déjà { ids: [...] } ; sinon du texte à parser
  let out = Array.isArray($json.ids) ? $json : $json.text;
  if (typeof out === 'string') {
    const m = out.match(/\{[\s\S]*\}/);
    out = JSON.parse(m ? m[0] : out);
  }
  ids = ((out && out.ids) || []).map(String);
} catch (e) {}

const STOP = new Set(['dans', 'pour', 'avec', 'sans', 'sous', 'plus', 'moins', 'leur', 'leurs', 'cette', 'entre', 'après', 'avant', 'depuis', 'comme', 'mais', 'tout', 'tous', 'nouveau', 'nouvelle', 'deux', 'trois', 'with', 'from', 'that', 'this', 'what', 'have', 'about', 'their', 'will', 'into', 'more', 'over']);
const words = (t) => new Set(
  t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .split(/[^a-z0-9]+/).filter(w => w.length >= 4 && !STOP.has(w) && !/^\d+$/.test(w))
);
const norm = (w) => w.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
// Noms propres et sigles : mot en majuscule hors début de titre, tout en capitales, ou lettres + chiffres (COP31)
const entities = (t) => new Set(
  t.split(/[^\p{L}\p{N}]+/u).filter((w, i) => w.length >= 3 && (
    /\p{L}/u.test(w) && /\d/.test(w) || /^\p{Lu}{3,}$/u.test(w) || (i > 0 && /^\p{Lu}\p{Ll}/u.test(w))
  )).map(norm).filter(w => !STOP.has(w))
);
const PROMO = /bon plan|promo|black friday|singles day|soldes|offre|deal|réduction|à prix|prix (fou|cassé|mini|choc|bas)|-\d+ ?%|\d+ ?€/i;

const picked = [];
const tryAdd = (n) => {
  if (!n || picked.length >= MAX || picked.includes(n) || PROMO.test(n.title)) return;
  const w = words(n.title), e = entities(n.title);
  const dup = picked.some(p => {
    const pw = words(p.title), pe = entities(p.title);
    return [...pw].filter(x => w.has(x)).length >= 2 || [...e].some(x => pw.has(x)) || [...pe].some(x => w.has(x));
  });
  if (!dup) picked.push(n);
};
[...new Set(ids)].forEach(id => tryAdd(byId.get(id)));
cands.forEach(tryAdd);
return picked.map(n => ({ json: n }));

// Une seule entrée pour le LLM : les 6 news retenues (id | titre | description)
const news = $input.all().map(i => i.json);
const articles = news
  .map(n => `[${n.id}] ${n.title}\n${(n.description || '').slice(0, 400)}`)
  .join('\n\n');
return [{ json: { count: news.length, articles } }];

// Assemble l'email en deux versions (HTML + texte de secours) :
// news retenues + résumés du LLM (avec repli sur la description)
const user = $('Utilisateur').first().json;
const news = $('Top 6').all().map(i => i.json);

let summaries = {};
try {
  let out = Array.isArray($json.summaries) ? $json : $json.text;
  if (typeof out === 'string') {
    const m = out.match(/\{[\s\S]*\}/);
    out = JSON.parse(m ? m[0] : out);
  }
  for (const s of (out && out.summaries) || []) summaries[String(s.id)] = String(s.summary || '');
} catch (e) {}

// Le résumé vient d'un LLM nourri par du contenu externe : on le borne (pas d'URL, 350 caractères max)
const clean = (s) => s.replace(/https?:\/\/\S+|www\.\S+/gi, '').replace(/\s+/g, ' ').trim().slice(0, 350);
const fallback = (n) => (n.description || '').replace(/\s+/g, ' ').trim().slice(0, 250);
const items = news.map(n => ({ ...n, summary: clean(summaries[String(n.id)] || '') || fallback(n) }));

const date = DateTime.now().setZone(user.timezone || 'Europe/Paris').setLocale('fr').toFormat('cccc d LLLL');
const subject = `Ta newsletter Persona du ${date}`;
const footer = [
  'Tu reçois cet email parce que tu es inscrit à Persona.',
  'Pour changer tes sujets, ton horaire ou te désinscrire, il suffit de le demander dans le chat Persona.',
];

// --- Version texte (clients mail qui n'affichent pas le HTML) ---
const text = [
  `Bonjour ${user.username},`,
  '',
  `Voici ta sélection Persona du ${date} : ${items.length} news choisies pour toi.`,
  '',
  items.map((n, i) => `${i + 1}. ${n.title}\n${n.summary}\nSource : ${n.source}\n${n.url}`).join('\n\n'),
  '',
  '--',
  ...footer,
].join('\n');

// --- Version HTML ---
// Titres, résumés et sources viennent de flux RSS ou du LLM : tout est échappé (pas d'injection HTML)
// et seuls les liens http(s) sont acceptés.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const safeUrl = (u) => (/^https?:\/\//i.test(u || '') ? esc(u) : '#');
const LABELS = { tech: 'Tech', ai: 'IA', science: 'Science', economy: 'Économie', sport: 'Sport', culture: 'Culture', health: 'Santé', environment: 'Environnement', world: 'International' };
const dateCap = date.charAt(0).toUpperCase() + date.slice(1);

const cards = items.map((n, i) => `
<tr><td style="padding:20px 0;border-top:1px solid #e5e7eb;">
  <div style="font-size:12px;color:#6b7280;text-transform:uppercase;letter-spacing:0.04em;margin-bottom:6px;">${i + 1} &middot; ${esc(LABELS[n.topic_slug] || n.topic_slug)} &middot; ${esc(n.source)}</div>
  <a href="${safeUrl(n.url)}" style="font-size:18px;line-height:1.35;font-weight:700;color:#111827;text-decoration:none;">${esc(n.title)}</a>
  <p style="margin:8px 0 10px;font-size:15px;line-height:1.55;color:#374151;">${esc(n.summary)}</p>
  <a href="${safeUrl(n.url)}" style="font-size:14px;font-weight:600;color:#4f46e5;text-decoration:none;">Lire l'article &rarr;</a>
</td></tr>`).join('');

const html = `<!DOCTYPE html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(subject)}</title></head>
<body style="margin:0;padding:0;background:#f3f4f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;"><tr><td align="center" style="padding:24px 12px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border-radius:12px;">
<tr><td style="padding:28px 32px 8px;">
  <div style="font-size:22px;font-weight:800;color:#4f46e5;">Persona</div>
  <div style="font-size:14px;color:#6b7280;margin-top:2px;">${esc(dateCap)}</div>
  <p style="margin:20px 0 4px;font-size:16px;line-height:1.5;color:#111827;">Bonjour ${esc(user.username)},<br>voici les ${items.length} news choisies pour toi aujourd'hui.</p>
</td></tr>
<tr><td style="padding:0 32px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${cards}
</table></td></tr>
<tr><td style="padding:20px 32px 28px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.5;color:#9ca3af;">${footer.map(esc).join('<br>')}</td></tr>
</table>
</td></tr></table>
</body></html>`;

return [{ json: {
  user_id: user.id,
  to: user.email,
  subject,
  text,
  html,
  news_ids: items.map(n => n.id),
} }];

