-- Enregistre l'envoi : la newsletter, ses news (pour ne jamais les renvoyer) et last_sent_at (anti double envoi)
WITH nl AS (
  INSERT INTO newsletters (user_id) VALUES ($1::uuid) RETURNING id
), items AS (
  INSERT INTO newsletter_items (newsletter_id, news_id)
  SELECT nl.id, unnest($2::bigint[]) FROM nl
  RETURNING news_id
), upd AS (
  UPDATE users SET last_sent_at = now() WHERE id = $1::uuid
)
SELECT (SELECT id FROM nl) AS newsletter_id, (SELECT count(*) FROM items) AS news_count;

-- L'email n'est pas parti : on annule la réservation posée par le scheduler
-- pour qu'il réessaie à la minute suivante (tant qu'on est dans la fenêtre de 15 min).
UPDATE users SET last_sent_at = NULL WHERE id = $1::uuid RETURNING id AS user_id;
